ms.testRunner = function(container, exampleShape, decorationModel, screenSaver, mainController) {
	this.container = container;
	this.exampleShape = exampleShape;
	this.decorationModel = decorationModel;
	this.mainController = mainController;

	var caseLabel = document.createElement('span');
	caseLabel.innerHTML = 'Test Case:';
	caseLabel.className = 'gray';
	caseLabel.style = 'margin-left: 10px;';
	var groupLabel = document.createElement('span');
	groupLabel.innerHTML = 'Test Group:';
	groupLabel.className = 'gray';
	groupLabel.style = 'margin-left: 50px;';
	this.scenarioSelect = document.createElement('select');
	this.categorySelect = document.createElement('select');
	this.shapeSelect = document.createElement('select');
	this.shapeSelect.id = 'shape-select';
	this.categorySelect.addEventListener('change', this.onCategoryChange.bind(this));
	this.shapeSelect.addEventListener('change', this.onShapeChange.bind(this));
	
	var runButton = document.createElement('span');
	runButton.innerHTML = 'Run';
	runButton.className = 'inactive-mode';
	runButton.addEventListener("click", this.onRunClicked.bind(this));
	if (!ms.mvp) {
		var solveButton = document.createElement('span');
		solveButton.innerHTML = 'Solve';
		solveButton.className = 'inactive-mode';
		solveButton.addEventListener("click", this.onSolveClicked.bind(this));
	}

	container.appendChild(caseLabel);
	container.appendChild(this.categorySelect);
	container.appendChild(this.shapeSelect);
	container.appendChild(groupLabel);
	container.appendChild(this.scenarioSelect);
	container.appendChild(runButton);
	!ms.mvp && container.appendChild(solveButton);

	this.scenarios = [];
	this.categories = [];
	this.activeCategory = null;
	this.activeShape = null;
	this.defaultScenarios = [];
	var full = new ms.testScenario('All');
	var scenario2D = new ms.testScenario('2D');
	var scenario3D = new ms.testScenario('3D');	
	this.addScenario(full);	
	this.addScenario(scenario2D);	
	this.addScenario(scenario3D);
	
	if (ms.mvp) {
		var solutions = JSON.parse(LZString.decompressFromBase64(ms.mvpSolutions));
		solutions.forEach((solution) => {
			var is3D = (solution.category == '3D Shapes');
			var scenario = is3D ? scenario3D : scenario2D;
			this.addShape(solution.category, solution.name, [scenario], solution.data, solution.settings, solution.solution);
		});
	} else {
		this.addShapeData(scenario2D, scenario3D);
	}
	this.insertCategories();
	
	// ================================================================================================================================================================================================== //
	/******************************************************************************************************************************************************************************************************/
	/*********************************************************************** Default Shape ****************************************************************************************************************/
	/******************************************************************************************************************************************************************************************************/
	// this.setShape('3D Shapes', 'Generated Rules');
	// this.setShape('2D Branches', 'H');
	// ms.globalSettings.set('Bend Lines', true);
	// This gives us the old cost weights.
	if (true) {
		// ms.globalSettings.set('Bad Vertex', 40);
		ms.globalSettings.set('Face', 30);
		ms.globalSettings.set('Completion', 20);
		ms.globalSettings.set('State Density', 0);
		ms.globalSettings.set('Component Scale', 0);
	}
	
	ms.globalSettings.set('Seed', 1);
	// ms.globalSettings.set('Winding Enabled', false);
	// ms.globalSettings.set('Max Time Enabled', true);
	// ms.globalSettings.set('Face', 40);
	// ms.globalSettings.set('Completion', 40);
	ms.globalSettings.set('Task Stop', -1);
	// ms.globalSettings.set('Node Debug', -1);
	// ms.globalSettings.set('Ideal Length', 0.2);
	ms.globalSettings.set('Remove Good Vertices', true);

	var allShapes = [];
	this.categories.forEach(function(category) {
		category.shapes.forEach(function(shape) {
			full.addShape(shape);
		});
	});
};

